import json,urllib.request,datetime,time
base='http://127.0.0.1:17448'
out={'at':datetime.datetime.now().isoformat(),'target':'R45','kind':'read_only_cdp_live_soak','samples':[]}
def get(path,timeout=5):
 with urllib.request.urlopen(base+path,timeout=timeout) as r:return json.load(r)
before=get('/api/operator-lifecycle',4)
watchdog=get('/api/supervisor-watchdog?detect=0',4).get('config',{})
if before.get('queuePaused') is not True or watchdog.get('mode')!='off' or watchdog.get('allowAutonomousSend') is not False:raise RuntimeError('not frozen')
for i in range(2):
 started=time.perf_counter()
 try:
  x=get('/api/supervisor-watchdog/managed-chats?inspect=1',timeout=28)
  out['samples'].append({'sample':i,'ms':round((time.perf_counter()-started)*1000),'count':len(x.get('chats',[])),'inspected':x.get('inspected'),'chats':[{k:z.get(k) for k in ('name','status','highMode','openTabs','error') if k in z} for z in x.get('chats',[])[:9]]})
 except Exception as e:out['samples'].append({'sample':i,'ms':round((time.perf_counter()-started)*1000),'error':type(e).__name__})
x=get('/api/operator-lifecycle',4);w=get('/api/supervisor-watchdog?detect=0',4).get('config',{})
out['holdAfter']={'queuePaused':x.get('queuePaused'),'mode':w.get('mode'),'allowAutonomousSend':w.get('allowAutonomousSend')}
out['no_autonomy_resume']=out['holdAfter']=={'queuePaused':True,'mode':'off','allowAutonomousSend':False}
print(json.dumps(out,ensure_ascii=True)[:9200])
